/**
 * Signature hero widgets: one per specialty, each showing the thing that specialty is actually paid by
 * (minutes, units, levels, lesions, visits, eyes, specimens…). They share the glass card shell of the
 * cardiology beat strip, loop slowly while on screen, and pause off screen.
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { motion, AnimatePresence, useInView } from 'motion/react';
import { Check } from 'lucide-react';

/** Step counter that only runs while the widget is on screen. */
function useTick(n: number, ms: number) {
  const ref = useRef<HTMLDivElement>(null);
  const on = useInView(ref, { amount: 0.2 });
  const [k, setK] = useState(0);
  useEffect(() => {
    if (!on) return;
    const id = setInterval(() => setK((v) => (v + 1) % n), ms);
    return () => clearInterval(id);
  }, [on, n, ms]);
  return { ref, k };
}

function Shell({ wref, label, value, unit, children, lines }: {
  wref: React.RefObject<HTMLDivElement | null>; label: string; value: ReactNode; unit?: string; children: ReactNode;
  lines: [string, string, boolean][];
}) {
  return (
    <div className="ecg w-card w-glass sw [border-radius:2.17rem] [border:1.5px_solid_rgba(255,_255,_255,_0.7)] [background:linear-gradient(168deg,_rgba(255,_255,_255,_0.85)_8%,_rgba(242,_240,_255,_0.74)_92%)] [box-shadow:0_1.55rem_4.66rem_rgba(128,_70,_251,_0.35),_inset_0_1.5px_0_rgba(255,_255,_255,_0.9)] [backdrop-filter:blur(2.5rem)] [font-family:var(--f-man)] [color:#0d0c15] [padding:2.4rem]" ref={wref}>
      <div className="ecg__head [display:flex] [justify-content:space-between] [align-items:baseline] [font-size:1.5rem] [color:#575568] [&_span]:[display:inline-flex] [&_span]:[align-items:center] [&_span]:[gap:0.8rem] [&_span_i]:[width:0.7rem] [&_span_i]:[height:0.7rem] [&_span_i]:[border-radius:50%] [&_span_i]:[background:var(--purple)] [&_span_i]:[box-shadow:0_0_0_0.4rem_rgba(106,_65,_249,_0.16)] [&_span_i]:[animation:jy-pulse-p_1.4s_ease-in-out_infinite] [&_b]:[font-weight:700] [&_b]:[font-size:2.6rem] [&_b]:[color:#0d0c15] [&_b]:[font-variant-numeric:tabular-nums] [&_b_small]:[font-weight:500] [&_b_small]:[font-size:1.3rem] [&_b_small]:[color:#575568]"><span><i />{label}</span><b>{value}{unit && <small> {unit}</small>}</b></div>
      <div className="sw__viz [display:grid] [align-items:center] [position:relative] [margin:1.6rem_-0.4rem_0.8rem] [min-height:14rem] [padding:1.6rem_1.8rem] [border-radius:1.2rem] [background-color:rgba(255,_255,_255,_0.6)] [background-image:linear-gradient(rgba(106,_65,_249,_0.08)_1px,_transparent_1px),_linear-gradient(90deg,_rgba(106,_65,_249,_0.08)_1px,_transparent_1px)] [background-size:1.2rem_1.2rem]">{children}</div>
      <ul className="ecg__rows [&_li]:[display:grid] [&_li]:[grid-template-columns:6.4rem_1fr_auto] [&_li]:[gap:1.2rem] [&_li]:[align-items:center] [&_li]:[padding:1rem_0] [&_li]:[border-top:1px_solid_rgba(212,_209,_230,_0.7)] [&_li]:[font-size:1.35rem] [&_code]:[font-family:var(--f-mono)] [&_code]:[color:var(--purple)] [&_code]:[background:rgba(229,_223,_255,_0.8)] [&_code]:[border-radius:0.6rem] [&_code]:[padding:0.3rem_0.6rem] [&_code]:[text-align:center] [&_span]:[color:#575568] [&_em]:[font-style:normal] [&_em]:[font-weight:700] [&_em]:[font-size:1.2rem] [&_em]:[padding:0.3rem_0.9rem] [&_em]:[border-radius:3rem] [&_em]:[display:inline-flex] [&_em]:[align-items:center] [&_em]:[gap:0.3rem] [&_em]:[white-space:nowrap] [&_em]:[color:#8a83a8] [&_em]:[background:rgba(255,_255,_255,_0.7)]">
        {lines.map(([code, what, on]) => (
          <li key={code + what}>
            <code>{code}</code><span>{what}</span>
            <AnimatePresence mode="wait" initial={false}>
              <motion.em key={on ? 'y' : 'n'} className={on ? String.raw`is-ok [@media(max-width:_767px)]:[.lk\_\_mob_li&]:[background:#f6f3ff] [@media(max-width:_767px)]:[.lk\_\_mob_li&]:[border-color:#ddd3ff] [.ecg\_\_rows_em&]:[color:var(--purple)] [.ecg\_\_rows_em&]:[background:#ebe5ff] [.se\_\_dots_i&]:[background:#b7a3ff]` : ''} initial={{ y: 8, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -8, opacity: 0 }} transition={{ duration: 0.25 }}>
                {on ? <><Check size={13} strokeWidth={3} /> Coded</> : 'In review'}
              </motion.em>
            </AnimatePresence>
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ---------- Mental health: the session clock picks the code ---------- */
function Session() {
  const { ref, k } = useTick(62, 140); // minutes 0..61
  const m = k;
  const code = m >= 53 ? '90837' : m >= 38 ? '90834' : m >= 16 ? '90832' : '—';
  const R = 52, C = 2 * Math.PI * R;
  return (
    <Shell wref={ref} label="Telehealth session, live" value={m} unit="min" lines={[['90832', '16–37 min', m >= 16 && m < 38], ['90834', '38–52 min', m >= 38 && m < 53], ['90837', '53+ min', m >= 53]]}>
      <div className="sw-clock [display:flex] [align-items:center] [gap:2.4rem] [&_svg]:[width:13rem] [&_svg]:[height:13rem] [&_svg]:[flex:none]">
        <svg viewBox="0 0 130 130">
          <circle cx="65" cy="65" r={R} className="sw-track [fill:none] [stroke:#ece6ff] [stroke-width:10]" />
          {[16, 38, 53].map((t) => { const a = (t / 60) * 2 * Math.PI - Math.PI / 2; return <line key={t} x1={65 + Math.cos(a) * 44} y1={65 + Math.sin(a) * 44} x2={65 + Math.cos(a) * 60} y2={65 + Math.sin(a) * 60} className="sw-mark [stroke:#b7a3ff] [stroke-width:2]" />; })}
          <circle cx="65" cy="65" r={R} className="sw-arc [fill:none] [stroke:var(--purple)] [stroke-width:10] [stroke-linecap:round] [transition:stroke-dashoffset_0.15s_linear]" strokeDasharray={C} strokeDashoffset={C * (1 - Math.min(m, 60) / 60)} transform="rotate(-90 65 65)" />
        </svg>
        <div className="sw-clock__code [&_small]:[display:block] [&_small]:[font-size:1.2rem] [&_small]:[color:#8a8ea0] [&_b]:[display:block] [&_b]:[font-family:var(--f-mono)] [&_b]:[font-size:3.6rem] [&_b]:[font-weight:500] [&_b]:[color:var(--purple)] [&_b]:[letter-spacing:-0.06em] [&_em]:[font-style:normal] [&_em]:[font-family:var(--f-mono)] [&_em]:[font-size:1.1rem] [&_em]:[color:#575568] [&_em]:[background:#f1edff] [&_em]:[border-radius:0.6rem] [&_em]:[padding:0.2rem_0.6rem]"><small>Bills as</small><b>{code}</b><em>POS 10 · 95</em></div>
      </div>
    </Shell>
  );
}

/* ---------- Psychiatry: med management + therapy minutes, side by side ---------- */
function SplitVisit() {
  const { ref, k } = useTick(48, 160); // therapy minutes 0..47
  const add = k >= 38 ? '90836' : k >= 16 ? '90833' : '—';
  return (
    <Shell wref={ref} label="Med visit + therapy" value={k} unit="therapy min" lines={[['99214', 'Med management, MDM', true], ['90833', 'Therapy add-on, 16–37', k >= 16 && k < 38], ['90836', 'Therapy add-on, 38–52', k >= 38]]}>
      <div className="sw-split [position:relative] [display:flex] [height:6.4rem] [border-radius:1.2rem] [background:#f4f1fc] [overflow:hidden] [&>div]:[display:flex] [&>div]:[align-items:flex-end] [&>div]:[padding:0.8rem_1rem] [&_small]:[font-size:1.1rem] [&_small]:[font-weight:600] [&_small]:[color:#fff] [&_small]:[white-space:nowrap]">
        <div className="sw-split__a [width:38%] [background:#b7a3ff]"><small>E/M · on MDM</small></div>
        <motion.div className="sw-split__b [background:var(--grad)] [min-width:0]" animate={{ width: `${(k / 52) * 62}%` }} transition={{ duration: 0.15, ease: 'linear' }}><small>Therapy</small></motion.div>
        <span className="sw-split__line [position:absolute] [top:0] [bottom:0] [border-left:1.5px_dashed_rgba(106,_65,_249,_0.45)] [font-family:var(--f-mono)] [font-size:1rem] [color:var(--purple)] [padding:0.2rem_0.3rem]" style={{ left: `${38 + (16 / 52) * 62}%` }}>16</span>
        <span className="sw-split__line [position:absolute] [top:0] [bottom:0] [border-left:1.5px_dashed_rgba(106,_65,_249,_0.45)] [font-family:var(--f-mono)] [font-size:1rem] [color:var(--purple)] [padding:0.2rem_0.3rem]" style={{ left: `${38 + (38 / 52) * 62}%` }}>38</span>
      </div>
      <p className="sw-note [font-size:1.3rem] [color:#575568] [margin-top:0.8rem] [&_b]:[color:var(--purple)] [&_b]:[font-family:var(--f-mono)] [.sw-wound_&]:[text-align:center]">Add-on: <b>{add}</b></p>
    </Shell>
  );
}

/* ---------- Anesthesia: base units + 15-minute time units ---------- */
